#include <cmath>
#include <algorithm>
extern "C" void render(const double *p, int n, float *out, int H, int W, double scale, double aa) {
  std::fill(out,out+H*W,0.f);
  for(int k=0;k<n-1;k++) {
    double dx=p[3*k+3]-p[3*k], dy=p[3*k+4]-p[3*k+1];
    double l=hypot(dx,dy); if(l<.01)continue;
    double ex=dx/l,ey=dy/l;
    int steps=std::max(2,(int)ceil(l/1.3));
    for(int j=0;j<=steps;j++){
      double f=(double)j/steps;
      double x=(p[3*k]*(1-f)+p[3*k+3]*f)*scale;
      double y=(p[3*k+1]*(1-f)+p[3*k+4]*f)*scale;
      double w=(p[3*k+2]*(1-f)+p[3*k+5]*f)*scale;
      if(w<.01)continue;
      double d=.9056445*w+7.38*scale;
      double nx=-ey,ny=ex,hw=w/2;
      int x0=std::max(0,(int)floor(std::min(x,x-d*ex)-fabs(hw*nx)-aa));
      int x1=std::min(W-1,(int)ceil(std::max(x,x-d*ex)+fabs(hw*nx)+aa));
      int y0=std::max(0,(int)floor(std::min(y,y-d*ey)-fabs(hw*ny)-aa));
      int y1=std::min(H-1,(int)ceil(std::max(y,y-d*ey)+fabs(hw*ny)+aa));
      for(int v=y0;v<=y1;v++)for(int u=x0;u<=x1;u++){
        double qx=u-x,qy=v-y,s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
        double a=d*(1-4*t*t/(w*w))-s;
        double g=sqrt(1+pow(8*d*t/(w*w),2));
        double sd=std::min(s,a/g);
        float val=std::max(0.,std::min(1.,sd/aa+.5));
        out[v*W+u]=std::max(out[v*W+u],val);
      }
    }
  }
}
